      "answer": "C",
      "statements": [],
      "explanation": "Phân tích từng phát biểu:\n(1) SAI: Cơ năng của vật dao động điều hòa được bảo toàn, là một hằng số không đổi theo thời gian, không biến thiên tuần hoàn.\n(2) ĐÚNG: Tại vị trí biên (x = ±A), vận tốc v = 0 nên W_đ = 0, khi đó cơ năng W = W_t = (1/2)*k*A^2.\n(3) SAI: Cơ năng W = (1/2)*m*ω^2*A^2 tỉ lệ thuận với BÌNH PHƯƠNG biên độ (A^2), không phải tỉ lệ thuận với biên độ A.\n(4) SAI: Khi đi từ VTCB ra biên, |x| tăng nên thế năng tăng, tốc độ giảm nên động năng giảm.\n(5) ĐÚNG: Khi đi từ biên về VTCB, |x| giảm nên thế năng giảm, tốc độ tăng nên động năng tăng.\n=> Có 2 phát biểu đúng là (2) và (5).",
