      "lesson_title": "Bài 5: Dao động tắt dần, dao động cưỡng bức, hiện tượng cộng hưởng",
      "type": "multiple_choice",
      "category": "exercise",
      "question": "Một người xách một xô nước đi trên đường mỗi bước đi dài 50 cm thì nước trong xô bị sóng sánh mạnh nhất. Vận tốc đi của người đó là 2,5 km/h. Chu kì dao động riêng của nước trong xô là:",
