      "lesson_title": "Bài 5: Dao động tắt dần, dao động cưỡng bức, hiện tượng cộng hưởng",
      "type": "short_answer",
      "category": "exercise",
      "question": "Một tàu hỏa chạy trên một đường ray, cứ cách khoảng 6,4 m trên đường ray lại có một rãnh nhỏ giữa chỗ nối các thanh ray. Chu kì dao động riêng của khung tàu trên các lò xo giảm xóc là 1,6 s. Tàu bị xóc mạnh nhất khi chạy với tốc độ bằng bao nhiêu?",
      "options": [],
      "answer": "",
      "statements": [],
      "explanation": "Tàu bị xóc mạnh nhất khi xảy ra hiện tượng cộng hưởng cơ học, nghĩa là chu kì tác dụng của các rãnh ray bằng chu kì dao động riêng của khung tàu: T = T_0 = 1,6 s.\nKhoảng cách giữa hai rãnh nhỏ: s = 6,4 m.\nTốc độ chạy của tàu hỏa: v = s / T = 6,4 / 1,6 = 4 m/s (tương đương 4 * 3,6 = 14,4 km/h).",
