      "lesson_title": "Bài 5: Dao động tắt dần, dao động cưỡng bức, hiện tượng cộng hưởng",
      "type": "short_answer",
      "category": "exercise",
      "question": "Một người xách một xô nước đi trên đường, mỗi bước đi được 50 cm. Chu kỳ dao động riêng của nước trong xô là 1s. Nước trong xô bị sóng sánh mạnh nhất khi người đó đi với tốc độ là bao nhiêu?",
