      "graph_type": null,
      "casio_tip": "Nhớ nhanh: t = 0.25 s = T/2, sau nửa chu kì vật từ VTCB theo chiều dương sẽ quay lại VTCB theo chiều âm => x = 0, v = -v_max = -32π cm/s."
