      "answer": "",
      "statements": [],
      "explanation": "a) Tần số góc: ω = 2π*f = 2π * 2 = 4π rad/s.\nÁp dụng hệ thức độc lập thời gian:\nA^2 = x^2 + (v / ω)^2 = 3^2 + (16π / 4π)^2 = 3^2 + 4^2 = 25 => A = 5 cm.\nb) Gia tốc của vật tính theo công thức a = -ω^2 * x:\nω^2 = (4π)^2 = 16π^2 (rad/s)^2 ≈ 160 (với π^2 = 10).\n- Tại vị trí biên:\n  + Biên dương x = +5 cm: a = -(4π)^2 * 5 = -80π^2 cm/s^2 = -0,8π^2 m/s^2 (≈ -8 m/s^2).\n  + Biên âm x = -5 cm: a = -(4π)^2 * (-5) = +80π^2 cm/s^2 = +0,8π^2 m/s^2 (≈ +8 m/s^2).\n  Độ lớn gia tốc cực đại tại biên là a_max = 80π^2 cm/s^2 ≈ 8 m/s^2.\n- Tại vị trí x = -2 cm:\n  a = -(4π)^2 * (-2) = 32π^2 cm/s^2 = 0,32π^2 m/s^2 (≈ 3,2 m/s^2).",
      "has_graph": false,
      "graph_type": null,
      "casio_tip": "Bấm √(3^2 + (16/4)^2) = 5 cm."
